import { useForm } from "react-hook-form"
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Input from "../../Input/Input";
import Boton from "../../Boton/Boton";
import './NuevoProveedor.css';
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";

export default function NuevoProveedor({ onGuardar, actualizarProveedores }) {

    //Recupero informacion del usuario logueado
    const { token } = useValidarSesion(); // obtener el token desde Zustand

    const { register, handleSubmit, formState: { errors }, reset } = useForm({
        defaultValues: {    //constante que devuleve todo lo del form
            id_prov: "777-7777",

        }

    });

    const onSubmit = async (data) => {
        try {
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/proveedor`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(data),
            });

            // Intentamos leer siempre la respuesta (aunque haya error)
            const dataRespuestaProveedor = await respuesta.json().catch(() => ({}));

            if (respuesta.ok) {
                actualizarProveedores.current();
                toast.success("Proveedor registrado correctamente.", { className: "__toaster_success" });
                onGuardar();
            } else {
                if (respuesta.status === 422 && dataRespuestaProveedor?.errors) {
                    const errores = Object.values(dataRespuestaProveedor.errors).flat().join('\n');
                    toast.error(errores, { className: "__toaster_error" });
                } else {
                    const mensajeError = dataRespuestaProveedor?.error || "Error al crear Proveedor.";
                    toast.error(mensajeError, { className: "__toaster_error" });
                }
            }
        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al registrar al proveedor.", { className: "__toaster_error" });
        }
    };


    return (
        <>

            <form onSubmit={handleSubmit(onSubmit)} className="__formulario_proveedor">
                <div className="__cuerpo_proveedor">
                    <div className="__primera_columna">
                        <Tarjeta descripcion="Nombre" forid="nombre" mensajeError={errors.nombre?.message}>
                            <Input
                                tipo="text"
                                id="nombre"
                                {...register("nombre", { required: { value: true, message: "Ingrese nombre del Proveedor" } })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Correo" forid="mail" mensajeError={errors.correo?.message}>
                            <Input
                                tipo="text"
                                id="mail"
                                placeholder="example@gmail.com"
                                {...register("correo", {
                                    required: { value: true, message: "Ingrese Correo" },
                                    pattern: { value: /^[a-zA-Z0-9_.+-]+@[a-zA-Z0-9-]+\.[a-zA-Z]{2,4}$/, message: "Correo No Valido" }
                                })}
                            />
                        </Tarjeta>
                    </div>
                    <div className="__segunda_columna">
                        <Tarjeta descripcion="Telefono" forid="tel" mensajeError={errors.telefono?.message}>
                            <Input
                                tipo="text"
                                id="tel"
                                placeholder="3878-375270"
                                {...register("telefono", {
                                    required: { value: true, message: "Ingrese Telefono" },
                                    pattern: { value: /^\d{3,4}-\d{6,7}$/, message: "Telefono No Valido" }
                                })}
                            />
                        </Tarjeta>
                    </div>
                </div>
                <div className="__boton_prov">
                    <Boton descripcion='Agregar' habilitado submit></Boton>
                </div>
            </form>
        </>
    )
}